const ocupadoAtual = flow.get('portaOcupada') || false;
const novoOcupado = !ocupadoAtual;
const agora = Math.floor(Date.now() / 1000);
let duracao = 0;

if (!novoOcupado) {
    const inicio = flow.get('inicioOcupacaoTs') || agora;
    duracao = Math.max(1, agora - inicio);
}

msg.payload = {
    estado: novoOcupado ? 'FECHADA' : 'ABERTA',
    ocupado: novoOcupado,
    uid_tag: 'SIMULADO:NODE-RED',
    duracao_ultimo_uso_seg: duracao,
    origem: 'NODE_RED_SIMULADOR',
    timestamp: agora
};

return msg;

const modoTeste = Boolean(msg.payload);
flow.set('limiteEmergenciaSeg', modoTeste ? 30 : 900);
return null;

let dados = msg.payload;
if (typeof dados === 'string') {
    try {
        dados = JSON.parse(dados);
    } catch (e) {
        dados = { estado: dados.trim().toUpperCase() };
    }
}

const estadoStr = (dados.estado || 'ABERTA').toUpperCase();
const portaFechada = (estadoStr === 'FECHADA' || estadoStr === 'OCUPADO' || dados.ocupado === true);
const estadoAnterior = flow.get('portaOcupada');
const agora = Math.floor(Date.now() / 1000);

flow.set('portaOcupada', portaFechada);

let usosHoje = flow.get('usosHoje') || 0;
let somaDuracoes = flow.get('somaDuracoes') || 0;

if (portaFechada && estadoAnterior !== true) {
    flow.set('inicioOcupacaoTs', agora);
} else if (!portaFechada && estadoAnterior === true) {
    let duracao = Number(dados.duracao_ultimo_uso_seg) || 0;
    if (duracao <= 0) {
        const inicio = flow.get('inicioOcupacaoTs') || agora;
        duracao = Math.max(1, agora - inicio);
    }
    usosHoje += 1;
    somaDuracoes += duracao;
    flow.set('usosHoje', usosHoje);
    flow.set('somaDuracoes', somaDuracoes);
    flow.set('inicioOcupacaoTs', 0);
}

const mediaSeg = usosHoje > 0 ? Math.round(somaDuracoes / usosHoje) : 0;
const minMedia = Math.floor(mediaSeg / 60);
const segMedia = mediaSeg % 60;
const textoMedia = `${minMedia}m ${segMedia}s`;

const msgCard = {
    payload: {
        fechada: portaFechada,
        titulo: portaFechada ? 'OCUPADO / PORTA FECHADA' : 'LIVRE / PORTA ABERTA',
        subtitulo: portaFechada
            ? 'Servo 90° | Vibração 600ms | Buzzer 500ms'
            : 'Servo 0° | Vibração 2x 150ms | Buzzer 2x 150ms',
        emergencia: false
    }
};

const msgUsos = {
    payload: `${usosHoje} uso(s) hoje`
};

const msgMedia = {
    payload: textoMedia
};

const msgGrafico = !portaFechada && estadoAnterior === true ? {
    topic: 'Usos por Horário',
    payload: usosHoje
} : null;

return [msgCard, msgUsos, msgMedia, msgGrafico];

const portaFechada = flow.get('portaOcupada') || false;
const inicio = flow.get('inicioOcupacaoTs') || 0;
const limite = flow.get('limiteEmergenciaSeg') || 30;

if (!portaFechada || inicio === 0) {
    return [
        { payload: '00:00 (Porta Livre)' },
        { payload: '🟢 Normal (Sem alertas)' }
    ];
}

const agora = Math.floor(Date.now() / 1000);
const decorrido = Math.max(0, agora - inicio);
const min = String(Math.floor(decorrido / 60)).padStart(2, '0');
const seg = String(decorrido % 60).padStart(2, '0');

const emEmergencia = decorrido >= limite;
const textoStatus = emEmergencia
    ? `🚨 ALERTA DE EMERGÊNCIA! Porta trancada há mais de ${limite}s!`
    : `🔒 Ocupado dentro do tempo normal (Limite: ${limite}s)`;

return [
    { payload: `${min}:${seg}` },
    { payload: textoStatus }
];
